399				return reflect.Value{}, err
400			}
401			maskedPtr := reflect.New(v.Elem().Type())
402			maskedPtr.Elem().Set(maskedElem)
403			return maskedPtr, nil
404		case reflect.Slice:
405			if v.IsNil() {
406				return v, nil
407			}
408			maskedSlice := reflect.MakeSlice(v.Type(), 0, v.Len())
409			for i := 0; i < v.Len(); i++ {
410				maskedElem, err := m.maskMapStructValue(v.Index(i))
